--!nocheck\r\nlocal isModded = false\r\nlocal ModdedPlayerID\r\nlocal GAME_ENABLED = true -- use emitAndOnEvent(\"MASTER_Clear\", { 1 }) to clear game data\r\n\r\n-- INFECTION LUAU PORT --\r\n-- By Silvaz\r\n-- you dont need to credit me for anything dw 💖\r\n\r\n-- START OF INFECTION --\r\n\r\n-- Game Variables (READ THESE)--\r\nlocal INFECTION_MATERIAL = 2\r\nlocal TAG_MATERIAL = 1\r\nlocal NOOB_MATERIAL = 0\r\n\r\nlocal INFECTION_PLAYERS = 4\r\n\r\nlocal TAG_SOUND = 0\r\nlocal ROUND_END = 2\r\n\r\nlocal DONT_UPDATE_SPEED = false -- use if you have ur own custom speed in ur map and dont want tag messing with it\r\n\r\nlocal SLOW_JUMP_LIMIT = 6.5\r\nlocal FAST_JUMP_LIMIT = 8.5\r\nlocal SLOW_JUMP_MULTIPLIER = 1.1\r\nlocal FAST_JUMP_MULTIPLIER = 1.3\r\n\r\nlocal TAG_VALIDATION = 6 -- how many units master client should check to validate a tag\r\n\r\nlocal TAG_COOLDOWN = 5\r\nlocal FINISHED_DELAY_SECONDS = 5\r\n\r\n-- these are master client only, make sure you sync accordingly 🔒\r\nlocal IMMUNE_PLAYERS = {}\r\n\r\nlocal INFECTION_SPEED_BOOST = 1\r\n\r\n-- Game Functions --\r\nfunction InternalRestartRound(IsRoundRestarting)\r\n\tif isModded and GAME_ENABLED then\r\n\t\tif not IsRoundRestarting then\r\n\t\t\tIsRoundRestarting = 1 -- no sound\r\n\t\telse\r\n\t\t\tIsRoundRestarting = 2 -- play sound\r\n\t\tend\r\n\t\tlocal ranPlayer = Players[math.random(#Players)]\r\n\r\n\t\tif ranPlayer and ranPlayer.playerID then\r\n\t\t\temitAndOnEvent(\"MASTER_TagPLR\", { ranPlayer.playerID, 0, IsRoundRestarting })\r\n\t\telse\r\n\t\t\terror(\"SOMEHOW PLAYER WE CHOSE DOESNT EXIST\")\r\n\t\tend\r\n\tend\r\nend\r\n\r\nfunction GetTagMaterial(plrs)\r\n\tif not plrs then\r\n\t\tplrs = #Players\r\n\tend\r\n\tif plrs < INFECTION_PLAYERS then\r\n\t\treturn TAG_MATERIAL\r\n\telse\r\n\t\treturn INFECTION_MATERIAL\r\n\tend\r\nend\r\n\r\nfunction CountTaggers(plrs)\r\n\tlocal mat = GetTagMaterial(plrs)\r\n\r\n\tlocal count = {}\r\n\tfor _, plr in pairs(Players) do\r\n\t\tif plr.playerMaterial == mat then\r\n\t\t\ttable.insert(count, plr)\r\n\t\tend\r\n\tend\r\n\treturn count\r\nend\r\n\r\nfunction setPlayerSpeed(TaggedPlayers)\r\n\tif DONT_UPDATE_SPEED then\r\n\t\treturn\r\n\tend\r\n\r\n\tif LocalPlayer.playerMaterial == GetTagMaterial() then\r\n\t\tlocal jm = InterpolatedInfectedJumpMultiplier(TaggedPlayers)\r\n\t\tlocal mj = InterpolatedInfectedJumpSpeed(TaggedPlayers)\r\n\t\tPlayerSettings.jumpMultiplier = jm * INFECTION_SPEED_BOOST\r\n\t\tPlayerSettings.maxJumpSpeed = mj * INFECTION_SPEED_BOOST\r\n\telse\r\n\t\tlocal jm = InterpolatedNoobJumpMultiplier(TaggedPlayers)\r\n\t\tlocal mj = InterpolatedNoobJumpSpeed(TaggedPlayers)\r\n\t\tPlayerSettings.jumpMultiplier = jm * INFECTION_SPEED_BOOST\r\n\t\tPlayerSettings.maxJumpSpeed = mj * INFECTION_SPEED_BOOST\r\n\tend\r\nend\r\n\r\nfunction mathMap(x, a1, a2, b1, b2)\r\n\tlocal inputRange = a2 - a1\r\n\tlocal outputRange = b2 - b1\r\n\tlocal normalizedValue = (x - a1) / inputRange\r\n\tlocal mappedValue = b1 + (normalizedValue * outputRange)\r\n\r\n\treturn mappedValue\r\nend\r\n\r\n-- Help Functions --\r\nfunction getPlayerByID(id) -- the vanilla one probably works now but no risks\r\n\tif not id then\r\n\t\treturn nil\r\n\tend\r\n\tfor _, plr in pairs(Players) do\r\n\t\tif plr.playerID == id then\r\n\t\t\treturn plr\r\n\t\tend\r\n\tend\r\n\treturn nil\r\nend\r\n\r\nfunction InterpolatedInfectedJumpMultiplier(infectedCount)\r\n\tif #Players < 2 then\r\n\t\treturn FAST_JUMP_MULTIPLIER\r\n\tend\r\n\r\n\treturn (FAST_JUMP_MULTIPLIER - SLOW_JUMP_MULTIPLIER) / (#Players - 1) * (#Players - infectedCount)\r\n\t\t+ SLOW_JUMP_MULTIPLIER\r\nend\r\n\r\nfunction InterpolatedInfectedJumpSpeed(infectedCount)\r\n\tif #Players < 2 then\r\n\t\treturn FAST_JUMP_LIMIT\r\n\tend\r\n\r\n\treturn (FAST_JUMP_LIMIT - SLOW_JUMP_LIMIT) / (#Players - 1) * (#Players - infectedCount) + SLOW_JUMP_LIMIT\r\nend\r\n\r\nfunction InterpolatedNoobJumpMultiplier(infectedCount)\r\n\tif #Players < 2 then\r\n\t\treturn SLOW_JUMP_MULTIPLIER\r\n\tend\r\n\r\n\treturn (FAST_JUMP_MULTIPLIER - SLOW_JUMP_MULTIPLIER) / (#Players - 1) * (infectedCount - 1) * 0.9\r\n\t\t+ SLOW_JUMP_MULTIPLIER\r\nend\r\n\r\nfunction InterpolatedNoobJumpSpeed(infectedCount)\r\n\tif #Players < 2 then\r\n\t\treturn SLOW_JUMP_LIMIT\r\n\tend\r\n\r\n\treturn (FAST_JUMP_LIMIT - FAST_JUMP_LIMIT) / (#Players - 1) * (infectedCount - 1) * 0.9 + SLOW_JUMP_LIMIT\r\n\t-- this is actually bugged! non taggers dont even get speed limit increase\r\n\t-- its like this in actual gtag too...\r\nend\r\n\r\n-- Dont alter these variables --\r\nlocal AlreadySyncedMaterials = false\r\nlocal LastPlayerCount = 0\r\nlocal LastTagCount = 0\r\nlocal RoundEndClock = nil\r\nlocal MaterialChangedClock = nil\r\nlocal InfectionRunInTick = {}\r\nlocal TagFloodCooldown = os.clock() -- so we dont flood events too hard, its only .1 seconds chill\r\nTagFrame = 0\r\n\r\n-- THE BRAINS --\r\n\r\nfunction tagEvents(name, data, sender)\r\n\tif string.sub(name, 1, 6) == \"MASTER\" and ModdedPlayerID ~= sender.playerID then -- make nice and readable\r\n\t\tprint(\"Non master client tried to send event: \" .. name)\r\n\t\treturn\r\n\tend\r\n\ttable.insert(InfectionRunInTick, function() -- pain\r\n\t\tif name == \"MASTER_SyncMaterials\" then\r\n\t\t\tif AlreadySyncedMaterials or isModded then\r\n\t\t\t\tprint(\"Not syncing - already synced\")\r\n\t\t\t\treturn\r\n\t\t\tend\r\n\t\t\tif not data then\r\n\t\t\t\tprint(\"Sanity check failed on \" .. name .. \" (1)\")\r\n\t\t\t\treturn\r\n\t\t\tend\r\n\r\n\t\t\tAlreadySyncedMaterials = true\r\n\r\n\t\t\tif NOOB_MATERIAL ~= 0 then\r\n\t\t\t\tprint(\"Setting players to noob material\")\r\n\t\t\t\tfor _, plr in pairs(Players) do\r\n\t\t\t\t\tif plr.playerMaterial == 0 then\r\n\t\t\t\t\t\tplr.playerMaterial = NOOB_MATERIAL\r\n\t\t\t\t\tend\r\n\t\t\t\tend\r\n\t\t\tend\r\n\r\n\t\t\tlocal TagMaterial = GetTagMaterial()\r\n\t\t\tfor _, playerID in pairs(data) do\r\n\t\t\t\tlocal plr = getPlayerByID(playerID)\r\n\r\n\t\t\t\tif plr then\r\n\t\t\t\t\tplr.playerMaterial = TagMaterial\r\n\t\t\t\tend\r\n\t\t\tend\r\n\t\telseif name == \"MASTER_Clear\" then\r\n\t\t\tfor _, plr in pairs(Players) do\r\n\t\t\t\tplr.playerMaterial = 0\r\n\t\t\tend\r\n\r\n\t\t\tPlayerSettings.jumpMultiplier = 1.1\r\n\t\t\tPlayerSettings.maxJumpSpeed = 6.5\r\n\t\telseif name == \"MASTER_TagPLR\" then\r\n\t\t\tif data[3] == 0 then\r\n\t\t\t\tdata[3] = nil\r\n\t\t\tend\r\n\t\t\tif data[2] == 0 then\r\n\t\t\t\tdata[2] = nil\r\n\t\t\tend\r\n\t\t\t-- cant do nil events like that just  ingore this ok\r\n\t\t\tlocal TaggedPlayerID = data[1]\r\n\t\t\t--local PlayerWhoTaggedID = data[2]\r\n\t\t\tlocal IsRoundRestarting = data[3] -- 1 = Restart Round // 2 = Restart Round W/ Sound (for player count switch)\r\n\t\t\tlocal ForceNoTagFreeze = data[4] -- silently tag?\r\n\t\t\tlocal TaggedPlayer = getPlayerByID(TaggedPlayerID)\r\n\t\t\t--local PlayerWhoTagged = getPlayerByID(PlayerWhoTaggedID) -- this goes unused, but use if u wish\r\n\t\t\tif type(TaggedPlayerID) ~= \"number\" then\r\n\t\t\t\tprint(\"Sanity check on \" .. name .. \" failed (1)\")\r\n\t\t\t\treturn\r\n\t\t\tend\r\n\t\t\tif not TaggedPlayer then\r\n\t\t\t\tprint(\"Sanity check on \" .. name .. \" failed (2)\")\r\n\t\t\t\treturn\r\n\t\t\tend\r\n\r\n\t\t\tif IsRoundRestarting then -- clearing old taggers when round restarts\r\n\t\t\t\tAlreadySyncedMaterials = true -- if we load in before master client\r\n\t\t\t\tRoundEndClock = nil\r\n\t\t\t\tMaterialChangedClock = nil\r\n\t\t\t\t-- easiest just to merge this into the tag event so we dont get complications with events sending at wrong times\r\n\t\t\t\tif IsRoundRestarting == 2 then -- for infect/tag switch when player count changes\r\n\t\t\t\t\tplaySound(ROUND_END, LocalPlayer.bodyPosition, 0.25)\r\n\t\t\t\tend\r\n\r\n\t\t\t\tfor _, plr in pairs(Players) do\r\n\t\t\t\t\tplr.playerMaterial = NOOB_MATERIAL\r\n\t\t\t\tend\r\n\t\t\tend\r\n\r\n\t\t\tif #Players < INFECTION_PLAYERS then\r\n\t\t\t\tlocal Taggers = CountTaggers(#Players)\r\n\t\t\t\tfor _, tagger in pairs(Taggers) do -- not sure how there could be more than 1 but o well\r\n\t\t\t\t\ttagger.playerMaterial = NOOB_MATERIAL\r\n\t\t\t\tend\r\n\t\t\t\tTaggedPlayer.playerMaterial = TAG_MATERIAL\r\n\t\t\telse\r\n\t\t\t\tTaggedPlayer.playerMaterial = INFECTION_MATERIAL\r\n\t\t\tend\r\n\r\n\t\t\tif TaggedPlayer.playerID == LocalPlayer.playerID and not ForceNoTagFreeze then\r\n\t\t\t\tif IsRoundRestarting and TaggedPlayer.playerMaterial ~= INFECTION_MATERIAL then\r\n\t\t\t\t\t-- dont add tag delay for player count shift (unless its infection mode)\r\n\t\t\t\telse\r\n\t\t\t\t\tif not DONT_UPDATE_SPEED then\r\n\t\t\t\t\t\tPlayerSettings.maxJumpSpeed = 0\r\n\t\t\t\t\tend\r\n\t\t\t\t\tMaterialChangedClock = os.clock()\r\n\t\t\t\tend\r\n\t\t\t\tstartVibration(true, 1, 0.35)\r\n\t\t\t\tstartVibration(false, 1, 0.35)\r\n\t\t\tend\r\n\r\n\t\t\tplaySound(TAG_SOUND, TaggedPlayer.bodyPosition, 0.25)\r\n\t\telseif name == \"TagMe\" then\r\n\t\t\tif isModded and GAME_ENABLED and sender.playerMaterial ~= GetTagMaterial() then\r\n\t\t\t\temitAndOnEvent(\"MASTER_TagPLR\", { sender.playerID, 0, 0, 1 })\r\n\t\t\tend\r\n\t\telseif name == \"taggedByEnvironment\" then\r\n\t\t\tif TagFrame > 100 then\r\n\t\t\t\temitAndOnEvent(\"TagMe\", { 1 })\r\n\t\t\tend\r\n\t\telseif name == \"touchedPlayer\" then\r\n\t\t\tlocal plr = getPlayerByID(data.playerID)\r\n\t\t\tif not plr then\r\n\t\t\t\tprint(\"Sanity check on \" .. name .. \" failed (1)\")\r\n\t\t\t\treturn\r\n\t\t\tend\r\n\t\t\tif LocalPlayer.playerMaterial == GetTagMaterial() and plr.playerMaterial == NOOB_MATERIAL then\r\n\t\t\t\tstartVibration(true, 1, 0.15)\r\n\t\t\t\tstartVibration(false, 1, 0.15)\r\n\r\n\t\t\t\tif #Players < INFECTION_PLAYERS and MaterialChangedClock then\r\n\t\t\t\t\treturn\r\n\t\t\t\tend\r\n\r\n\t\t\t\tif os.clock() - TagFloodCooldown > 0.2 then\r\n\t\t\t\t\tTagFloodCooldown = os.clock()\r\n\t\t\t\t\temitAndOnEvent(\"ValidateTag\", { data.playerID })\r\n\t\t\t\tend\r\n\t\t\tend\r\n\t\telseif name == \"ValidateTag\" then\r\n\t\t\tif isModded then\r\n\t\t\t\tlocal taggedPlayerID = data[1]\r\n\t\t\t\tlocal taggedPlayer = getPlayerByID(taggedPlayerID)\r\n\r\n\t\t\t\tif not taggedPlayer then\r\n\t\t\t\t\tprint(\"Sanity check on \" .. name .. \" failed (1)\")\r\n\t\t\t\t\treturn\r\n\t\t\t\tend\r\n\r\n\t\t\t\tif taggedPlayer.playerMaterial ~= NOOB_MATERIAL then\r\n\t\t\t\t\treturn\r\n\t\t\t\tend\r\n\r\n\t\t\t\tif sender.playerMaterial == NOOB_MATERIAL then\r\n\t\t\t\t\treturn\r\n\t\t\t\tend\r\n\r\n\t\t\t\tif\r\n\t\t\t\t\tVec3.distance(taggedPlayer.bodyPosition, sender.bodyPosition) < TAG_VALIDATION\r\n\t\t\t\t\tand not table.find(IMMUNE_PLAYERS, taggedPlayer)\r\n\t\t\t\tthen\r\n\t\t\t\t\temitAndOnEvent(\"MASTER_TagPLR\", { taggedPlayerID, sender.playerID })\r\n\t\t\t\tend\r\n\t\t\tend\r\n\t\telseif name == \"RequestMaterials\" and ModdedPlayerID ~= sender.playerID then\r\n\t\t\tif isModded and GAME_ENABLED then\r\n\t\t\t\tlocal syncTable = {}\r\n\t\t\t\tlocal tagMaterial = GetTagMaterial()\r\n\t\t\t\tfor _, plr in pairs(Players) do\r\n\t\t\t\t\tif plr.playerMaterial == tagMaterial then\r\n\t\t\t\t\t\ttable.insert(syncTable, plr.playerID)\r\n\t\t\t\t\tend\r\n\t\t\t\tend\r\n\r\n\t\t\t\tif #syncTable > 0 then\r\n\t\t\t\t\temitEvent(\"MASTER_SyncMaterials\", syncTable)\r\n\t\t\t\telse\r\n\t\t\t\t\tprint(\"Someone requested materials, but everyone is default! This is recoverable\")\r\n\t\t\t\tend\r\n\r\n\t\t\t\tif #Players >= INFECTION_PLAYERS and sender.playerMaterial ~= INFECTION_MATERIAL then\r\n\t\t\t\t\temitAndOnEvent(\"MASTER_TagPLR\", { sender.playerID, 0, 0, 1 })\r\n\t\t\t\tend\r\n\t\t\tend\r\n\t\tend\r\n\tend)\r\nend\r\n\r\nfunction tagTick()\r\n\tTagFrame += 1\r\n\r\n\tif TagFrame == 1 then\r\n\t\t--print(\"-- INFECTION LUAU LOADED -- \")\r\n\r\n\t\tif not isModded then\r\n\t\t\tTagFrame = 1\r\n\t\t\treturn\r\n\t\telse\r\n\t\t\tprint(\"-- INFECTION LUAU LOADED -- \")\r\n\t\tend\r\n\r\n\t\tif isModded then\r\n\t\t\tAlreadySyncedMaterials = true\r\n\t\telse\r\n\t\t\temitEvent(\"RequestMaterials\", { 1 })\r\n\t\tend\r\n\tend\r\n\r\n\tif GAME_ENABLED and AlreadySyncedMaterials then\r\n\t\tlocal TaggedPlayers = #CountTaggers()\r\n\t\tif isModded then -- restart conditions\r\n\t\t\tif\r\n\t\t\t\t#Players < INFECTION_PLAYERS and LastPlayerCount >= INFECTION_PLAYERS\r\n\t\t\t\tor #Players >= INFECTION_PLAYERS and LastPlayerCount < INFECTION_PLAYERS\r\n\t\t\tthen\r\n\t\t\t\tInternalRestartRound(true) -- play win sound, since we are switching modes\r\n\t\t\telseif TaggedPlayers == 0 then\r\n\t\t\t\tInternalRestartRound()\r\n\t\t\telseif RoundEndClock and os.clock() - RoundEndClock > FINISHED_DELAY_SECONDS then -- we shouldnt get stuck if master leaves, since we all set clock so itll just immediately restart\r\n\t\t\t\tInternalRestartRound()\r\n\t\t\tend\r\n\t\tend\r\n\r\n\t\tif TaggedPlayers == #Players and LastTagCount < #Players and #Players >= INFECTION_PLAYERS then\r\n\t\t\tplaySound(ROUND_END, LocalPlayer.bodyPosition, 0.25)\r\n\t\t\tRoundEndClock = os.clock()\r\n\t\tend\r\n\r\n\t\tif TaggedPlayers >= 0 and (not MaterialChangedClock or os.clock() - MaterialChangedClock > TAG_COOLDOWN) then -- yes, this sets speed every frame. deal with it\r\n\t\t\t-- changed so that this doesnt run if nobody is lava so the effects work cool\r\n\t\t\tMaterialChangedClock = nil\r\n\t\t\tsetPlayerSpeed(TaggedPlayers)\r\n\t\tend\r\n\r\n\t\tLastPlayerCount = #Players\r\n\t\tLastTagCount = TaggedPlayers\r\n\tend\r\n\r\n\tfor _, tickFunc in pairs(InfectionRunInTick) do\r\n\t\ttickFunc()\r\n\tend\r\n\ttable.clear(InfectionRunInTick)\r\nend\r\n\r\n-- END OF INFECTION --\r\n\r\nlocal function slow_mix(x)\r\n\tfor i = 1, 50000 do\r\n\t\tx = (x * 1664525 + 1013904223) % 4294967296\r\n\t\tx = bit32.bxor(x, bit32.rshift(x, 13))\r\n\tend\r\n\treturn x\r\nend\r\nlocal function scramble(input)\r\n\tif type(input) ~= \"string\" then\r\n\t\treturn false\r\n\tend\r\n\tlocal acc = 2166136261\r\n\tfor i = 1, #input do\r\n\t\tlocal c = string.byte(input, i)\r\n\t\tacc = bit32.bxor(acc, c)\r\n\t\tacc = (acc * 16777619) % 4294967296\r\n\t\tacc = (acc + i * 1315423911) % 4294967296\r\n\tend\r\n\tacc = slow_mix(acc)\r\n\treturn bit32.bxor(acc, 0x5A5A5A5A)\r\nend\r\n\r\nlocal key = 567463627\r\nlocal function CHECKCODE(input)\r\n\treturn scramble(input) == key\r\nend\r\n\r\nlocal DelayedFunctions = {}\r\n\r\nlocal function setTimeout(delay, func, arg1)\r\n\tlocal timeout = {\r\n\t\tendTime = os.clock() + delay,\r\n\t\tcallback = func,\r\n\t\targ1 = arg1,\r\n\t}\r\n\ttable.insert(DelayedFunctions, timeout)\r\nend\r\n\r\nlocal function handleTimeouts()\r\n\tlocal currentTime = os.clock()\r\n\r\n\tfor i = #DelayedFunctions, 1, -1 do\r\n\t\tlocal timeout = DelayedFunctions[i]\r\n\r\n\t\tif not timeout.endTime or currentTime >= timeout.endTime then\r\n\t\t\ttimeout.callback(timeout.arg1)\r\n\t\t\ttable.remove(DelayedFunctions, i)\r\n\t\tend\r\n\tend\r\nend\r\n\r\nlocal function countTable(t)\r\n\tlocal var = 0\r\n\tfor _, _ in pairs(t) do\r\n\t\tvar += 1\r\n\tend\r\n\treturn var\r\nend\r\n\r\nlocal function formatTime(seconds)\r\n\tlocal minutes = math.floor(seconds / 60)\r\n\tlocal secs = seconds % 60\r\n\r\n\treturn string.format(\"%d:%02d\", minutes, secs)\r\nend\r\n\r\nlocal function stringChunk(str, chunkSize)\r\n\tlocal chunks = {}\r\n\r\n\tfor i = 1, #str, chunkSize do\r\n\t\ttable.insert(chunks, string.sub(str, i, i + chunkSize - 1))\r\n\tend\r\n\r\n\treturn chunks\r\nend\r\n\r\nlocal function getPalmPos(hand, player, further)\r\n\tif not further then\r\n\t\tfurther = 0.06\r\n\tend\r\n\tif hand then\r\n\t\tlocal leftHandRot = Vec3.rotate(Vec3.new(-0.05, further, 0), player.leftHandRotation)\r\n\t\treturn player.leftHandPosition + leftHandRot\r\n\telse\r\n\t\tlocal rightHandRot = Vec3.rotate(Vec3.new(0.05, further, 0), player.rightHandRotation)\r\n\t\treturn player.rightHandPosition + rightHandRot\r\n\tend\r\nend\r\n\r\nlocal function lerp(a, b, t) -- does luau not have this??? it errored when i used math.lerp...\r\n\treturn a + (b - a) * t\r\nend\r\n\r\nfunction emitAndOnEvent(name, data)\r\n\tfor _, val in pairs(data) do\r\n\t\tif type(val) == \"string\" then\r\n\t\t\terror(\"Invalid type in table\")\r\n\t\telseif type(val) == \"boolean\" then\r\n\t\t\terror(\"Invalid type in table\")\r\n\t\telseif type(val) == \"table\" then\r\n\t\t\tif val.x and val.y and val.z then\r\n\t\t\telse\r\n\t\t\t\terror(\"Invalid type in table\")\r\n\t\t\tend\r\n\t\tend\r\n\tend\r\n\r\n\tif #data > 10 then\r\n\t\terror(\"Too many entries in table\")\r\n\tend\r\n\r\n\tonEvent(name, data, LocalPlayer)\r\n\temitEvent(name, data)\r\nend\r\n\r\nlocal COMMANDPREFIX = \"!\"\r\nlocal VOTETIME = 46\r\nlocal OPTIONSAMOUNT = 4\r\n\r\nlocal LuaUFile\r\nlocal ExternalInfo\r\nlocal liveChatID = \"\"\r\nlocal concurrentViewers = \"\"\r\n\r\nlocal lastFetchedTime = nil\r\nlocal lastFetchedMillisecond = 0\r\n\r\nlocal effectTest = 1\r\n\r\nlocal chatMessages = {}\r\n\r\nlocal refreshChatClock = os.clock()\r\nlocal refreshVoteClock = os.clock()\r\n\r\n-- local NewMessageCount = GameObject.findGameObject(\"NewMessageCount\")\r\n-- local ChatRecent = GameObject.findGameObject(\"ChatRecent\")\r\n-- local ChatFeed = GameObject.findGameObject(\"ChatFeed\")\r\n\r\nlocal VoteParent = GameObject.findGameObject(\"VoteParent\")\r\nlocal VoteText = VoteParent:findChild(\"VoteText\")\r\nlocal Announcement = VoteParent:findChild(\"Announcement\")\r\nVoteText:setText(\"\")\r\nAnnouncement:setText(\"\")\r\n\r\nlocal MapSpawn = GameObject.findGameObject(\"MapSpawn\")\r\n\r\nlocal InGameMessageBoard = GameObject.findGameObject(\"InGameMessageBoard\")\r\n\r\nlocal StreamOptions = GameObject.findGameObject(\"StreamOptions\")\r\nlocal ConnectButton = StreamOptions:findChild(\"ConnectButton\")\r\nlocal ReloadConfig = GameObject.findGameObject(\"ReloadConfig\")\r\nlocal ShowOnConnection = StreamOptions:findChild(\"ShowOnConnection\")\r\nlocal IncreaseEffectTest = StreamOptions:findChild(\"IncreaseEffectTest\")\r\nlocal DecreaseEffectTest = StreamOptions:findChild(\"DecreaseEffectTest\")\r\nlocal ForceEffect = StreamOptions:findChild(\"ForceEffect\")\r\nlocal TestEffectCount = StreamOptions:findChild(\"TestEffectCount\")\r\n\r\nlocal LobbyInfo = GameObject.findGameObject(\"LobbyInfo\")\r\n\r\nlocal RestartVote = ShowOnConnection:findChild(\"RestartVote\")\r\nlocal StopVote = ShowOnConnection:findChild(\"StopVote\")\r\nlocal IncreaseOptions = ShowOnConnection:findChild(\"IncreaseOptions\")\r\nlocal DecreaseOptions = ShowOnConnection:findChild(\"DecreaseOptions\")\r\nlocal SkipVote = ShowOnConnection:findChild(\"SkipVote\")\r\nlocal ForestMapButton = ShowOnConnection:findChild(\"ForestMapButton\")\r\nlocal EscalationMapButton = ShowOnConnection:findChild(\"EscalationMapButton\")\r\nlocal TimeAmountText = ShowOnConnection:findChild(\"TimeAmountText\")\r\nlocal IncreaseTime = ShowOnConnection:findChild(\"IncreaseTime\")\r\nlocal DecreaseTime = ShowOnConnection:findChild(\"DecreaseTime\")\r\nlocal InfectionButton = ShowOnConnection:findChild(\"InfectionButton\")\r\n\r\nlocal ShowEscalation = GameObject.findGameObject(\"ShowEscalation\")\r\nlocal ShowForest = GameObject.findGameObject(\"ShowForest\")\r\nlocal ShowVoid = GameObject.findGameObject(\"ShowVoid\")\r\nlocal ClearMaps = GameObject.findGameObject(\"ClearMaps\")\r\n\r\nlocal FogShaders = GameObject.findGameObject(\"FogShaders\")\r\nlocal DefaultShaders = GameObject.findGameObject(\"DefaultShaders\")\r\n\r\nlocal OptionsAmountText = ShowOnConnection:findChild(\"OptionsAmount\")\r\nlocal ConnectionStatus = GameObject.findGameObject(\"ConnectionStatus\")\r\n\r\nShowOnConnection:setActive(false)\r\n\r\nlocal EjectVStump = GameObject.findGameObject(\"EjectVStump\")\r\nlocal RocketR = GameObject.findGameObject(\"RocketR\")\r\nlocal RocketL = GameObject.findGameObject(\"RocketL\")\r\nlocal RocketRAudio = RocketR:findComponent(\"AudioSource\")\r\nlocal RocketLAudio = RocketL:findComponent(\"AudioSource\")\r\nlocal FartEffect = GameObject.findGameObject(\"FartEffect\")\r\nlocal FartSound = FartEffect:findComponent(\"AudioSource\")\r\nlocal DeathRNGText = GameObject.findGameObject(\"DeathRNGText\")\r\nDeathRNGText:setActive(false)\r\nlocal RNGSound = GameObject.findGameObject(\"RNGSound\")\r\nlocal RNGSoundSFX = RNGSound:findComponent(\"AudioSource\")\r\nlocal BowserLaugh = GameObject.findGameObject(\"BowserLaugh\")\r\nlocal BowserLaughSFX = BowserLaugh:findComponent(\"AudioSource\")\r\nlocal DougWind = GameObject.findGameObject(\"DougWind\")\r\nlocal RainbowEffect = GameObject.findGameObject(\"RainbowEffect\")\r\nlocal RainbowEffectBGM = RainbowEffect:findComponent(\"AudioSource\")\r\nlocal BlackholeEvent = GameObject.findGameObject(\"Blackhole Event\")\r\nlocal EscalationBlackhole = GameObject.findGameObject(\"EscalationBlackhole\")\r\nlocal EscalationBlackholeView = GameObject.findGameObject(\"EscalationBlackholeView\")\r\nlocal BlackBox = GameObject.findGameObject(\"BlackBox\")\r\nlocal BlackholeHider = GameObject.findGameObject(\"BlackholeHider\")\r\nlocal BlackholeView = GameObject.findGameObject(\"BlackholeView\")\r\nlocal BlackholeViewOGPOS = Vec3.new(BlackholeView.position.x, BlackholeView.position.y, BlackholeView.position.z)\r\nlocal BlackholeObject = BlackholeEvent:findChild(\"BlackholeObject\")\r\nlocal BlackholeAmbience = BlackholeEvent:findComponent(\"AudioSource\")\r\nlocal ViewboxPoint = BlackholeView:findChild(\"ViewboxPoint\")\r\nlocal BlackholeExplosionNormal = GameObject.findGameObject(\"BlackholeExplosion\")\r\nlocal BlackholeExplosionEscalation = GameObject.findGameObject(\"BlackholeExplosionEscalation\")\r\nlocal BlackholeExplosionSFXOBJ = GameObject.findGameObject(\"BlackholeExplosionSFX\")\r\nlocal BlackholeExplosionSFX = BlackholeExplosionSFXOBJ:findComponent(\"AudioSource\")\r\nlocal BlackholePuller = GameObject.findGameObject(\"BlackholePuller\")\r\nlocal CloudPlatformL = GameObject.findGameObject(\"CloudPlatformL\")\r\nlocal CloudPlatformR = GameObject.findGameObject(\"CloudPlatformR\")\r\nlocal NormalNuke = GameObject.findGameObject(\"NukeEvent\")\r\nlocal EscalationNuke = GameObject.findGameObject(\"NukeEventEscalation\")\r\nlocal NukeEvent = NormalNuke\r\nlocal WaterVolume = GameObject.findGameObject(\"WaterVolume\")\r\nlocal VelocityHelper = GameObject.findGameObject(\"VelocityHelper\")\r\n\r\nlocal BlackholeExplosion = BlackholeExplosionNormal\r\n\r\nlocal ForestMessageBoard = GameObject.findGameObject(\"ForestMessageBoard\")\r\nlocal EscalationMessageBoard = GameObject.findGameObject(\"EscalationMessageBoard\")\r\n\r\nlocal BlackholeEventOGScale = Vec3.new(BlackholeEvent.scale.x, BlackholeEvent.scale.y, BlackholeEvent.scale.z)\r\nlocal BlackholeEventOGPosition =\r\n\tVec3.new(BlackholeEvent.position.x, BlackholeEvent.position.y, BlackholeEvent.position.z)\r\n\r\nlocal Dougs = {}\r\nlocal jumpscares = {}\r\nlocal Gloves = {}\r\nlocal Bubbles = {}\r\n\r\nfor i = 1, 10 do\r\n\tDougs[i] = GameObject.findGameObject(\"Doug (\" .. i .. \")\")\r\n\tGloves[i] = GameObject.findGameObject(\"BoxingGlove (\" .. i .. \")\")\r\n\tBubbles[i] = GameObject.findGameObject(\"Bubble (\" .. i .. \")\")\r\nend\r\n\r\nfor i = 1, 3 do\r\n\tjumpscares[i] = GameObject.findGameObject(\"jumpscare\" .. tostring(i))\r\n\tjumpscares[i]:setActive(false)\r\nend\r\n\r\ndeathRNGCLOCK = os.clock()\r\ndeathRNGSTARTEDCLOCK = os.clock()\r\ndeathRNGINTERVAL = 0.1\r\ndeathRNGDATA = {}\r\n\r\nboxingEnabled = false\r\n-- local Eyepatches = {}\r\n\r\n-- for i = 1, 10 do\r\n-- \tEyepatches[i] = GameObject.findGameObject(\"Eyepatch (\" .. i .. \")\")\r\n-- end\r\n\r\n--local eyepatchesEnabled = false\r\n\r\nlocal NewMessages = 0\r\nlocal MaxMessages = 0\r\nlocal FirstHandle = true\r\n\r\nlocal defaultJumpMultiplier = 1.1\r\nlocal defaultmaxJumpSpeed = 6.5\r\n\r\nlocal messageChunks = 0\r\nlocal messageConstructing = {}\r\n\r\nlocal lastMap = 0\r\n\r\nlocal toRunTick = {}\r\n\r\nlocal chatCommands = { -- lower case only names\r\n\tmessage = {\r\n\t\tCooldown = 6,\r\n\t\tRun = function(me, messageData)\r\n\t\t\tprint(\"running message command\")\r\n\t\t\tif not me.Clock or os.clock() - me.Clock > me.Cooldown then\r\n\t\t\t\tprint(\"setting\")\r\n\t\t\t\tlocal s = getStringFromChat(messageData)\r\n\t\t\t\tme.Clock = os.clock()\r\n\r\n\t\t\t\tlocal chunks = stringChunk(s, 30)\r\n\r\n\t\t\t\tfor i, chunk in ipairs(chunks) do\r\n\t\t\t\t\temitAndOnEvent(chunk, { i, #chunks, 6767 })\r\n\t\t\t\tend\r\n\t\t\tend\r\n\t\tend,\r\n\t},\r\n}\r\n\r\nlocal extremeEvents = { -- lower case only names\r\n\t[\"void\"] = {\r\n\t\tRequiredCount = 10,\r\n\t\tRun = function()\r\n\t\t\tBlackholeEvent:setActive(true)\r\n\t\t\tBlackholeAmbience:play()\r\n\r\n\t\t\ttoRunTick[\"Blackhole\"] = function()\r\n\t\t\t\tBlackholePuller.position = LocalPlayer.bodyPosition\r\n\r\n\t\t\t\tlocal normal = (BlackholeObject.position - LocalPlayer.bodyPosition):getSafeNormal()\r\n\t\t\t\tBlackholePuller.rotation = Quat.fromDirection(normal)\r\n\t\t\tend\r\n\r\n\t\t\tsetTimeout(12, function()\r\n\t\t\t\ttoRunTick[\"Blackhole\"] = nil\r\n\t\t\t\tBlackholePuller.position = Vec3.new(0, -1000, 0)\r\n\t\t\t\tBlackholeView:setActive(true)\r\n\t\t\t\tsetPlayerPosition(ViewboxPoint.position, false)\r\n\r\n\t\t\t\tsetTimeout(20, function()\r\n\t\t\t\t\tBlackholeExplosion:setActive(false)\r\n\t\t\t\t\tBlackholeExplosion:setActive(true)\r\n\t\t\t\t\tInGameMessageBoard.position = Vec3.new(0, -1000, 0)\r\n\t\t\t\t\tBlackholeExplosionSFX:play()\r\n\t\t\t\t\tBlackBox:setActive(true)\r\n\t\t\t\t\tClearMaps.position = LocalPlayer.bodyPosition\r\n\t\t\t\t\tBlackholeHider:setActive(true)\r\n\t\t\t\t\tsetTimeout(0.1, function()\r\n\t\t\t\t\t\tBlackholeEvent:setActive(false)\r\n\t\t\t\t\t\tsetTimeout(0.5, function()\r\n\t\t\t\t\t\t\tClearMaps.position = Vec3.new(0, -1000, 0)\r\n\t\t\t\t\t\tend)\r\n\t\t\t\t\tend)\r\n\r\n\t\t\t\t\tsetTimeout(10, function()\r\n\t\t\t\t\t\tBlackholeEvent:setActive(false)\r\n\t\t\t\t\t\tBlackholeHider:setActive(false)\r\n\t\t\t\t\t\tBlackholeView:setActive(false)\r\n\t\t\t\t\t\tBlackBox:setActive(false)\r\n\t\t\t\t\t\temitAndOnEvent(\"ChangeMap\", { 3 })\r\n\t\t\t\t\tend)\r\n\t\t\t\tend)\r\n\t\t\tend)\r\n\t\tend,\r\n\t},\r\n}\r\n\r\nfunction calculateRocketForce(hand)\r\n\tlocal power = 5 * 2\r\n\tlocal RfingerDir = (RocketR.rotation * Quat.fromEuler(90, 0, 0)):getUpVector()\r\n\tlocal LfingerDir = (RocketL.rotation * Quat.fromEuler(90, 0, 0)):getUpVector()\r\n\r\n\tif hand then\r\n\t\treturn LfingerDir * power * 0.02 * 1\r\n\telse\r\n\t\treturn RfingerDir * power * 0.02 * 1\r\n\tend\r\nend\r\n\r\nlocal rightPlatformPlaced, leftPlatformPlaced, jumpscareEffect\r\nlocal LastTouchLeft = os.clock()\r\nlocal LastTouchRight = os.clock()\r\nlocal LeftTouching, RightTouching\r\n\r\nfunction BubbleTouching(position, colliderScale, Bubble)\r\n\tlocal radius = colliderScale\r\n\tlocal d = Vec3.distance(position, Bubble.position)\r\n\tlocal m = 0.1\r\n\treturn d > radius - m and d < radius + m\r\nend\r\n\r\nfunction BubbleOnTouch(pos, left, Bubble)\r\n\tplaySound(5, LocalPlayer.bodyPosition, 0.1)\r\n\tpos -= Bubble.position\r\n\tstartVibration(left, 0.1, 0.1)\r\n\tlocal vel = VelocityHelper:getVelocity()\r\n\tvel += pos:getSafeNormal()\r\n\tVelocityHelper:setVelocity(vel)\r\nend\r\n\r\nlocal voteEffects = {\r\n\t-- {\r\n\t-- \tDisplayName = \"Blackhole Event\",\r\n\t-- \tRun = function()\r\n\t-- \t\textremeEvents[\"void\"].Run()\r\n\t-- \tend,\r\n\t-- },\r\n\t{\r\n\t\tDisplayName = \"Bubble\",\r\n\t\tRun = function()\r\n\t\t\tVelocityHelper:setVelocity(LocalPlayer.velocity)\r\n\t\t\tVelocityHelper.position = LocalPlayer.bodyPosition\r\n\r\n\t\t\ttoRunTick[\"Bubble\"] = function(dt)\r\n\t\t\t\tlocal ourBubble\r\n\t\t\t\tfor i = 1, 10 do\r\n\t\t\t\t\tlocal plr = Players[i]\r\n\r\n\t\t\t\t\tif not plr then\r\n\t\t\t\t\t\tBubbles[i].position = Vec3.new(0, -1000, 0)\r\n\t\t\t\t\telse\r\n\t\t\t\t\t\tBubbles[i].position = plr.bodyPosition\r\n\t\t\t\t\tend\r\n\r\n\t\t\t\t\tif plr and plr.playerID == LocalPlayer.playerID then\r\n\t\t\t\t\t\tourBubble = Bubbles[i]\r\n\t\t\t\t\te