hestVote.Table.Index, highestVote.Votes)\r\n\r\n\ttable.clear(currentVote)\r\n\tsetupVote()\r\nend\r\n\r\nfunction onHttpGet(url, result)\r\n\tif string.find(url, \"liveStreamingDetails\") then\r\n\t\tlocal succ, err = pcall(function()\r\n\t\t\tlocal data = jsonDecode(result)\r\n\r\n\t\t\tif data and type(data) == \"table\" then\r\n\t\t\t\tlocal validStream = false\r\n\r\n\t\t\t\tfor _, item in pairs(data.items) do\r\n\t\t\t\t\tvalidStream = true\r\n\t\t\t\t\tliveChatID = item.liveStreamingDetails.activeLiveChatId\r\n\t\t\t\t\tconcurrentViewers = item.liveStreamingDetails.concurrentViewers\r\n\t\t\t\t\tprint(\"Successfully set live chat id to \" .. tostring(liveChatID))\r\n\t\t\t\t\tbreak\r\n\t\t\t\tend\r\n\r\n\t\t\t\tif validStream and liveChatID then\r\n\t\t\t\t\tsetTimeout(0, function()\r\n\t\t\t\t\t\tShowOnConnection:setActive(true)\r\n\t\t\t\t\t\tConnectionStatus:setText(\r\n\t\t\t\t\t\t\t\"CONNECTED SUCCESSFULLY!\\nVIEWERS (NOT UPDATING): \" .. tostring(concurrentViewers)\r\n\t\t\t\t\t\t)\r\n\t\t\t\t\tend)\r\n\t\t\t\telseif validStream and concurrentViewers and not liveChatID then\r\n\t\t\t\t\tsetTimeout(0, function()\r\n\t\t\t\t\t\tConnectionStatus:setText(\r\n\t\t\t\t\t\t\t\"<color=yellow>FAILED TO CONNECT\\nVALID ID, VIEWER COUNT FOUND BUT NO CHAT\\nIS CHAT DISABLED?\"\r\n\t\t\t\t\t\t)\r\n\t\t\t\t\tend)\r\n\t\t\t\telseif validStream and not concurrentViewers and not liveChatID then\r\n\t\t\t\t\tsetTimeout(0, function()\r\n\t\t\t\t\t\tConnectionStatus:setText(\r\n\t\t\t\t\t\t\t\"<color=yellow>FAILED TO CONNECT\\nVALID ID, NO CHAT OR VIEWER COUNT FOUND\\nIS THE STREAM STILL LIVE?\"\r\n\t\t\t\t\t\t)\r\n\t\t\t\t\tend)\r\n\t\t\t\telseif not validStream then\r\n\t\t\t\t\tsetTimeout(0, function()\r\n\t\t\t\t\t\tConnectionStatus:setText(\"<color=yellow>FAILED TO CONNECT\\nNO ITEMS FOUND\\nINVALID STREAM ID\")\r\n\t\t\t\t\tend)\r\n\t\t\t\tend\r\n\t\t\tend\r\n\t\tend)\r\n\r\n\t\tif err then\r\n\t\t\tConnectionStatus:setText(\"<color=yellow>FAILED TO CONNECT\\nINTERNAL ERROR\\nAPI EXHAUSTED?\")\r\n\t\tend\r\n\telseif string.find(url, \"liveChat/messages\") then\r\n\t\tlocal data = jsonDecode(result)\r\n\t\tNewMessages = 0\r\n\t\tMaxMessages = 0\r\n\t\tprint(\"data is \" .. tostring(result))\r\n\t\tif data and type(data) == \"table\" and data.items then\r\n\t\t\tlocal messages = data.items\r\n\t\t\tlocal highestTime = 0\r\n\t\t\tlocal latestMillisecond = 0\r\n\r\n\t\t\tprint(\"recieved data: \" .. tostring(#data))\r\n\r\n\t\t\tfor _, message in ipairs(messages) do\r\n\t\t\t\tif message and message.snippet and message.snippet.publishedAt and message.snippet.displayMessage then\r\n\t\t\t\t\tlocal messageTime = message.snippet.publishedAt\r\n\r\n\t\t\t\t\tlocal messageTimestamp = os.time({\r\n\t\t\t\t\t\tyear = tonumber(messageTime:sub(1, 4)),\r\n\t\t\t\t\t\tmonth = tonumber(messageTime:sub(6, 7)),\r\n\t\t\t\t\t\tday = tonumber(messageTime:sub(9, 10)),\r\n\t\t\t\t\t\thour = tonumber(messageTime:sub(12, 13)),\r\n\t\t\t\t\t\tmin = tonumber(messageTime:sub(15, 16)),\r\n\t\t\t\t\t\tsec = tonumber(messageTime:sub(18, 19)),\r\n\t\t\t\t\t})\r\n\r\n\t\t\t\t\tlocal millisecond = tonumber(messageTime:sub(21, 23))\r\n\t\t\t\t\tprint(\r\n\t\t\t\t\t\t\"Message Time: \"\r\n\t\t\t\t\t\t\t.. tostring(messageTimestamp)\r\n\t\t\t\t\t\t\t.. \" / Last Fetched: \"\r\n\t\t\t\t\t\t\t.. tostring(lastFetchedTime)\r\n\t\t\t\t\t)\r\n\r\n\t\t\t\t\tif lastFetchedTime == nil or messageTimestamp >= lastFetchedTime then\r\n\t\t\t\t\t\tif lastFetchedTime and messageTimestamp == lastFetchedTime then\r\n\t\t\t\t\t\t\tif millisecond <= lastFetchedMillisecond then\r\n\t\t\t\t\t\t\t\tprint(\"millisecond not right, continuing\")\r\n\t\t\t\t\t\t\t\tcontinue\r\n\t\t\t\t\t\t\tend\r\n\t\t\t\t\t\tend\r\n\r\n\t\t\t\t\t\tlocal tableToAdd = {\r\n\t\t\t\t\t\t\t[\"Text\"] = message.snippet.displayMessage,\r\n\t\t\t\t\t\t\t[\"DisplayName\"] = message.authorDetails.displayName,\r\n\t\t\t\t\t\t\t[\"ChannelID\"] = message.authorDetails.channelId,\r\n\t\t\t\t\t\t\t[\"Time\"] = messageT